public int toysBrute(int[] w) {
    Arrays.sort(w);
    int n = w.length, best = n;
    for (int mask = 1; mask < (1 << n); mask++) {
        boolean[] covered = new boolean[n];
        int count = 0;
        for (int b = 0; b < n; b++) {
            if ((mask & (1 << b)) != 0) {
                count++;
                for (int j = 0; j < n; j++) {
                    if (w[j] >= w[b] && w[j] <= w[b] + 4) covered[j] = true;
                }
            }
        }
        boolean all = true;
        for (boolean c : covered) all &= c;
        if (all) best = Math.min(best, count);
    }
    return best;
}

