from itertools import combinations

def toys_brute(w: list[int]) -> int:
    w = sorted(w)
    n = len(w)
    for size in range(1, n + 1):
        for anchors in combinations(range(n), size):
            covered = [False] * n
            for a in anchors:
                for j in range(n):
                    if w[a] <= w[j] <= w[a] + 4:
                        covered[j] = True
            if all(covered):
                return size
    return n

